    INSERT INTO public.profiles (id, full_name, email, avatar_url)
INSERT INTO public.cities (id, name, state, country, description, image_url) VALUES
(1, 'Coimbatore', 'Tamil Nadu', 'India', 'The Manchester of South India, blessed with cool Nilgiri breezes, spiritual landmarks, and vibrant engineering.', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800'),
(2, 'Chennai', 'Tamil Nadu', 'India', 'Gateway to the South, famed for Marina Beach, Dravidian temples, rich Carnatic music, and sea breezes.', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800'),
(3, 'Ooty', 'Tamil Nadu', 'India', 'Queen of Hill Stations with rolling tea estates, cool misty mountains, and heritage toy train rides.', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800'),
(4, 'Madurai', 'Tamil Nadu', 'India', 'The Cultural Capital of Tamil Nadu, celebrated for the towering Meenakshi Amman Temple and midnight food streets.', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800'),
(5, 'Salem', 'Tamil Nadu', 'India', 'Surrounded by emerald hills, silver jewelry craft, sweet mango orchards, and the serene heights of Yercaud.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800'),
(6, 'Bengaluru', 'Karnataka', 'India', 'India''s Silicon Valley and Garden City, home to sprawling parks, craft microbreweries, and grand palaces.', 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?w=800'),
(7, 'Kodaikanal', 'Tamil Nadu', 'India', 'Princess of Hill Stations, crowned by serene Kodai lake, misty cliffside paths, cascading waterfalls, and fragrant pine valleys.', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800'),
(8, 'Pondicherry', 'Puducherry', 'India', 'The French Riviera of the East, famed for French colonial boulevards, pastel villas, Auroville, peaceful beaches, and seaside cafes.', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800'),
(9, 'Kanyakumari', 'Tamil Nadu', 'India', 'The southernmost tip of mainland India where the three oceans meet, famed for the Vivekananda Rock Memorial and sunrise vistas.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800'),
(10, 'Thanjavur', 'Tamil Nadu', 'India', 'The historical capital of the Great Living Chola Empire, celebrated for the colossal Brihadeeswara Big Temple and Saraswathi Mahal Library.', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800'),
(11, 'Mysuru', 'Karnataka', 'India', 'The Royal City of Palaces, famed for the grand illuminated Amba Vilas Palace, Chamundi Hills, sandalwood, and silk.', 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?w=800'),
(12, 'Munnar', 'Kerala', 'India', 'Verdant jewel of God''s Own Country nestled amidst sprawling emerald tea plantations, rolling clouds, waterfalls, and wildlife.', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800')
INSERT INTO public.places (id, city_id, name, description, category, image_url, address, latitude, longitude, opening_hours, entry_fee, rating) VALUES
(1, 1, 'Adiyogi Shiva & Isha Yoga Center', 'An awe-inspiring 112-foot tall bust of Adiyogi consecrated by Sadhguru, nestled at the foot of Velliangiri Mountains. Features the consecrated Dhyanalinga, Surya Kund, and dynamic evening light show.', 'Temple', 'assets/places/adiyogi.jpg', 'Velliangiri Foothills, Ishana Vihar, Coimbatore', 10.975, 76.7408, '6:00 AM - 8:00 PM', 'Free', 4.9),
(2, 1, 'Marudhamalai Murugan Temple', 'Perched atop a granite hill with panoramic vistas of Coimbatore. Believed to possess healing herbs and medicinal spring waters associated with Sage Pambatti Siddhar.', 'Temple', 'assets/places/marudhamalai.jpg', 'Maruthamalai Adivaram, Coimbatore', 11.0458, 76.8524, '6:00 AM - 8:30 PM', 'Free', 4.8),
(3, 1, 'Siruvani Waterfalls & Dam', 'Famed globally for yielding the second tastiest drinking water on Earth. Set amidst dense Western Ghats reserve forests with crystal streams cascading through rocks.', 'Nature', 'assets/places/siruvani.jpg', 'Siruvani Hills, Sadivayal, Coimbatore', 10.9419, 76.6908, '10:00 AM - 3:30 PM', '₹50', 4.7),
(4, 1, 'Gedee Car Museum', 'The only classic automobile museum of its caliber in South India. Houses vintage Rolls Royces, Benz three-wheelers, micro-cars, and unique steam and petrol innovations.', 'Museum', 'assets/places/gedee_cars.jpg', 'Avanashi Road, Race Course, Coimbatore', 11.0022, 76.974, '9:00 AM - 6:30 PM', '₹100', 4.7),
(5, 1, 'Brookefields Mall & Cross-Cut Road', 'Coimbatore''s premier lifestyle shopping and dining center, accompanied by the legendary silk and traditional jewellery streets of Gandhipuram.', 'Shopping', 'assets/places/brookefields.jpg', 'Dr Krishnasamy Mudaliar Rd, Brookefields, Coimbatore', 11.0105, 76.9589, '10:00 AM - 10:00 PM', 'Free', 4.6),
(6, 1, 'Eachanari Vinayagar Temple', 'Famous 6-foot tall idol of Lord Ganesha dating back to 1500 AD, originally bound for Madurai but blessed permanently on the Pollachi Highway.', 'Temple', 'assets/places/eachanari.jpg', 'Pollachi Main Rd, Eachanari, Coimbatore', 10.925, 76.978, '5:30 AM - 9:00 PM', 'Free', 4.8),
(7, 1, 'Perur Pateeswarar Temple', 'Centuries-old temple built by Karikala Chola on the banks of Noyyal River, boasting exquisite stone-carved Kanaka Sabha pillars depicting celestial dance poses.', 'Historical', 'assets/places/perur.jpg', 'Siruvani Main Road, Perur, Coimbatore', 10.9733, 76.9205, '6:00 AM - 1:00 PM, 4:00 PM - 8:30 PM', 'Free', 4.7),
(8, 1, 'Monkey Falls & Aliyar Dam Park', 'Scenic natural rapids tumbling into serene forest pools, complemented by the boating reservoir, rose garden, and aquarium park of Aliyar.', 'Nature', 'assets/places/aliyar_dam.jpg', 'Pollachi-Valparai Ghat Road, Aliyar', 10.49, 76.96, '7:00 AM - 5:00 PM', '₹30', 4.6),
(9, 1, 'Gass Forest Museum & Innovation Hub', 'Established in 1902 by Horace Arris Gass, housing rare preserved botanical, timber, geological, and wildlife specimens inside the Forest College campus.', 'Museum', 'assets/places/gass_forest.jpg', 'Forest College Campus, RS Puram, Coimbatore', 11.018, 76.945, '9:00 AM - 5:30 PM', '₹20', 4.5),
(10, 1, 'Valparai Hill Station & Tea Valleys', 'A serene hill haven perched 3,500 feet high, navigated via 40 hairpin bends with leopard corridors, misty tea plateaus, and roaring Sholayar waters.', 'Adventure', 'assets/places/tnau_garden.jpg', 'Anamalai Tiger Reserve Range, Coimbatore District', 10.326, 76.955, '6:00 AM - 6:00 PM (Ghat Entry)', 'Free', 4.8),
(11, 1, 'Kovai Kutralam Waterfalls', 'Magnificent forest waterfall located within the protected Siruvani Reserve. Crystal-clear mountain currents cascading over rock slabs surrounded by dense green canopy.', 'Nature', 'assets/places/kovai_kutralam.jpg', 'Chadivayal, Siruvani Reserve, Coimbatore', 10.938, 76.685, '10:00 AM - 3:00 PM', '₹50', 4.7),
(12, 1, 'VOC Park, Zoo & Science Center', 'Iconic central park featuring sprawling recreational green lawns, children''s mini-train, aviary and a regional science park with interactive physics exhibits.', 'Entertainment', 'assets/places/voc_park.jpg', 'Park Gate Road, Gandhipuram, Coimbatore', 11.008, 76.968, '10:00 AM - 7:30 PM', '₹25', 4.5),
(13, 2, 'Marina Beach & Promenade', 'The second-longest natural urban beach in the world, spanning 13 km along the Coromandel coast with iconic statues, morning sea breezes, and twilight sundal vendors.', 'Beach', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Kamarajar Salai, Triplicane, Chennai', 13.0499, 80.2824, 'Open 24/7', 'Free', 4.7),
(14, 2, 'Kapaleeshwarar Temple, Mylapore', 'A grand 7th-century Dravidian architectural marvel dedicated to Lord Shiva, renowned for its rainbow-hued Gopuram, temple tank, and vibrant Panguni Peruvizha festivities.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Vadakkumada St, Mylapore, Chennai', 13.0336, 80.2694, '6:00 AM - 12:30 PM, 4:00 PM - 9:00 PM', 'Free', 4.8),
(15, 2, 'Fort St. George & Museum', 'Built in 1644 by the British East India Company, marking the origin of modern Madras. Houses St. Mary''s Church, grand colonial ramparts, and priceless antiquities.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Rajaji Salai, Fort St George, Chennai', 13.0797, 80.2871, '9:00 AM - 5:00 PM (Closed Fridays)', '₹25', 4.6),
(16, 2, 'Guindy National Park & Children''s Park', 'One of the very few national parks situated right inside a metropolis. Protected haven for blackbucks, spotted deer, golden jackals, rare butterflies, and exotic avifauna.', 'Nature', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Rangeguindy, Guindy, Chennai', 13.0067, 80.2206, '9:00 AM - 5:30 PM (Closed Tuesdays)', '₹20', 4.5),
(17, 2, 'San Thome Basilica', 'A soaring neo-Gothic Catholic cathedral built over the tomb of St. Thomas the Apostle, who arrived in India in 52 AD. Features stunning stained-glass windows.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', '38 San Thome High Rd, Mylapore, Chennai', 13.0336, 80.2783, '6:00 AM - 9:00 PM', 'Free', 4.8),
(18, 2, 'Edward Elliot''s Beach & Besant Nagar', 'A peaceful coastal haven featuring the historic Karl Schmidt Memorial, scenic ocean boardwalk, vibrant seaside cafes, and quiet evening breezes.', 'Beach', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Besant Nagar Beach Rd, Chennai', 13.0007, 80.2731, 'Open 24/7', 'Free', 4.6),
(19, 2, 'DakshinaChitra Living Heritage Village', 'A cross-cultural living museum showcasing reconstructed heritage homes, folk dances, glass blowing, and artisan craft workshops of Tamil Nadu, Kerala, Karnataka, and Andhra.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'East Coast Road, Muttukadu, Chennai', 12.8236, 80.2417, '10:00 AM - 6:00 PM (Closed Tuesdays)', '₹175', 4.8),
(20, 2, 'Government Museum Chennai & Bronze Gallery', 'India''s second oldest museum complex dating to 1851, housing the world''s most magnificent collection of ancient Chola bronze sculptures including Nataraja.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Pantheon Road, Egmore, Chennai', 13.0694, 80.2572, '9:30 AM - 5:00 PM (Closed Fridays)', '₹50', 4.6),
(21, 2, 'Arignar Anna Zoological Park (Vandalur Zoo)', 'Spanning 1,265 acres, this is one of Southeast Asia''s largest open zoological parks, housing lion safaris, white tigers, chimpanzees, and a nocturnal animal house.', 'Nature', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Grand Southern Trunk Rd, Vandalur, Chennai', 12.8797, 80.0817, '9:00 AM - 5:00 PM (Closed Tuesdays)', '₹90', 4.7),
(22, 2, 'Mahabalipuram Shore Temple & Pancha Rathas', 'UNESCO World Heritage rock-cut sanctuaries sculpted by the Pallava dynasty right on the crashing waves of Bay of Bengal. Monumental stone chariots and giant relief of Arjuna''s Penance.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'East Coast Road, Mamallapuram, Chennai Region', 12.616, 80.198, '6:00 AM - 6:00 PM', '₹40', 4.9),
(23, 2, 'Valluvar Kottam Cultural Monument', 'Grand stone monument dedicated to the legendary Tamil philosopher-poet Thiruvalluvar. Shaped like a colossal 128-foot temple chariot holding all 1,330 verses of the Thirukkural.', 'Historical', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Tirumurthy Nagar, Nungambakkam, Chennai', 13.053, 80.241, '8:30 AM - 5:30 PM', '₹10', 4.6),
(24, 2, 'Semmozhi Poonga Botanical Garden', 'A lush 20-acre landscaped eco-botanical garden in the city center featuring over 500 species of medicinal plants, vertical gardens, bonsai courtyards, and tranquil water lily pools.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Cathedral Road, Teynampet, Chennai', 13.048, 80.252, '10:00 AM - 7:30 PM', '₹25', 4.6),
(25, 3, 'Government Botanical Garden', 'Laid out in 1848 on the terraced lower slopes of Doddabetta Peak over 55 sprawling acres, home to a 20-million-year-old fossilized tree trunk, Italian floral terraces, and rare fern houses.', 'Nature', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800', 'Vannarapettai, Ooty, Tamil Nadu', 11.4184, 76.7118, '7:00 AM - 6:30 PM', '₹50', 4.8),
(26, 3, 'Doddabetta Peak & Telescope House', 'The highest summit in the Nilgiri Mountains rising to 8,650 feet. Offers breathtaking 360-degree vistas across mist-cloaked valley slopes and the Chamundi Hills of Mysore.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Doddabetta, Ooty, Tamil Nadu', 11.401, 76.736, '9:00 AM - 6:00 PM', '₹20', 4.7),
(27, 3, 'Pykara Waterfalls & Lake Boating', 'Sacred river of the Toda tribes flowing through rolling Toda settlements before plummeting down stepped granite rocks and opening into a pristine lake boathouse.', 'Nature', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Pykara, Nilgiris District, Tamil Nadu', 11.52, 76.595, '9:30 AM - 5:30 PM', '₹30', 4.8),
(28, 3, 'Nilgiri Mountain Heritage Railway', 'UNESCO World Heritage meter-gauge rack-and-pinion steam train built in 1908, winding through 16 tunnels, 250 bridges, and romantic Nilgiri tea cliffs.', 'Historical', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800', 'Ooty Railway Station, Nilgiris, Tamil Nadu', 11.406, 76.696, 'Trains operate per Southern Railway schedule', '₹205', 4.9),
(29, 3, 'Government Rose Garden & Elk Hill Slopes', 'Perched at 7,200 feet on the slopes of Elk Hill, this is India''s largest rose garden showcasing over 20,000 cultivars of hybrid tea roses, miniature roses, and ramblers.', 'Nature', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 'Elk Hill Slopes, Ooty, Tamil Nadu', 11.4068, 76.715, '8:30 AM - 6:00 PM', '₹40', 4.7),
(30, 3, 'Ooty Lake & Boathouse', 'An artificial lake created in 1824 by John Sullivan stretching over 65 scenic acres. Features pedal boats, motor launches, cycling tracks, and amusement rides along the shore.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'North Lake Road, Ooty, Tamil Nadu', 11.4045, 76.687, '9:00 AM - 6:00 PM', '₹30', 4.5),
(31, 3, 'Avalanche Lake & Shola Eco-Sanctuary', 'Formed naturally by a landslide in 1823, this tranquil high-altitude water body is surrounded by thick magnolia, rhododendron, and dense Shola cloud forests.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Avalanche Valley, Nilgiris, Tamil Nadu', 11.3, 76.58, '9:00 AM - 3:00 PM (Forest Safari entry)', '₹150', 4.9),
(32, 3, 'Emerald Lake & Silent Valley Tea Country', 'A peaceful turquoise jewel secluded in the Silent Valley region, framed by rolling tea plantations, exotic birdlife, and fragrant eucalyptus groves.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Emerald Village, Nilgiris, Tamil Nadu', 11.325, 76.618, '6:00 AM - 6:00 PM', 'Free', 4.8),
(33, 3, 'Mudumalai Tiger Reserve & Elephant Safari', 'Nestled at the tri-junction of Tamil Nadu, Karnataka, and Kerala, this premier tiger reserve shelters Bengal tigers, Asiatic elephants, Indian leopards, and gaur.', 'Adventure', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Gudalur-Mysore Highway, Theppakadu, Nilgiris', 11.58, 76.53, '6:00 AM - 10:00 AM, 2:00 PM - 6:00 PM', '₹350', 4.8),
(34, 3, 'Pine Forest & Shooting Medu', 'Soaring British-era cedar and pine plantations sloping down into scenic valley hollows. A beloved movie filming setting with needle-strewn paths and fragrant mountain air.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Cairn Hill Road, Ooty', 11.398, 76.671, '8:30 AM - 6:00 PM', '₹20', 4.7),
(35, 3, 'Dolphin''s Nose & Catherine Falls View', 'A dramatic rock cliff resembling a dolphin''s snout, jutting thousands of feet over the ravines with panoramic viewpoints of Catherine Falls plunging into deep chasms.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Coonoor Range, Nilgiris District', 11.348, 76.845, '9:00 AM - 5:30 PM', '₹30', 4.8),
(36, 3, 'Tea Factory & Highfield Chocolate Museum', 'Working factory perched on Dodabetta slope showcasing orthodox Nilgiri tea processing from fresh green leaves to steaming tea tasting, with live chocolate crafting.', 'Museum', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', 'Dodabetta Road, Ooty', 11.411, 76.728, '9:00 AM - 6:30 PM', '₹30', 4.6),
(37, 4, 'Meenakshi Amman Temple', 'The crown jewel of Dravidian architecture, with 14 colossal Gopurams, the Ashta Shakti Mandapam, the Hall of Thousand Pillars, and the sacred Golden Lotus Tank.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Madurai Main, Madurai, Tamil Nadu', 9.9195, 78.1193, '5:00 AM - 12:30 PM, 4:00 PM - 10:00 PM', 'Free', 4.9),
(38, 4, 'Thirumalai Nayakkar Mahal', 'A classical 17th-century palace built by King Tirumala Nayaka, celebrated for its monumental 82-foot stucco pillars, celestial dome, and nightly sound-and-light show.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Panthadi, Madurai, Tamil Nadu', 9.9149, 78.1245, '9:00 AM - 5:00 PM (Light show at 6:45 PM)', '₹50', 4.7),
(39, 4, 'Gandhi Memorial Museum & Tamukkam Palace', 'Housed in the 17th-century palace of Rani Mangammal, this historic museum preserves the blood-stained dhoti worn by Mahatma Gandhi when he was assassinated in 1948.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Tamukkam, Madurai, Tamil Nadu', 9.932, 78.136, '10:00 AM - 1:00 PM, 2:00 PM - 5:45 PM', 'Free', 4.7),
(40, 4, 'Alagar Kovil & Pazhamudircholai Murugan Temple', 'A forested temple dedicated to Lord Vishnu set against the Alagar Hills, paired with Pazhamudircholai, one of the sacred Arupadai Veedu shrines of Lord Murugan.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Alagar Kovil Hills, Madurai District', 10.076, 78.214, '6:00 AM - 8:00 PM', 'Free', 4.8)
INSERT INTO public.places (id, city_id, name, description, category, image_url, address, latitude, longitude, opening_hours, entry_fee, rating) VALUES
(41, 4, 'Vandiyur Mariamman Teppakulam', 'A monumental square temple reservoir covering 16 acres with a picturesque granite Maiya Mandapam pavilion in the center, famed for the glittering Float Festival.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Teppakulam, Madurai, Tamil Nadu', 9.912, 78.151, 'Open 24/7', 'Free', 4.6),
(42, 4, 'Samanar Malai Ancient Jain Rock Caves', 'Ancient rocky hill boasting 2,000-year-old rock-cut Jain carvings, stone inscriptions, and natural caverns where Jain monks meditated in tranquility.', 'Historical', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Keelakuyilkudi, Madurai District', 9.918, 78.058, '6:00 AM - 6:00 PM', 'Free', 4.7),
(43, 4, 'Koodal Azhagar Temple', 'One of the 108 Divya Desams, this ancient temple dedicated to Lord Vishnu features three distinct tiers displaying the deity in sitting, standing, and reclining postures.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Perumal Kovil Sannathi St, Madurai', 9.915, 78.114, '5:30 AM - 12:00 PM, 4:00 PM - 9:00 PM', 'Free', 4.7),
(44, 4, 'Kazimar Big Mosque & Maqbara', 'The oldest Islamic monument in Madurai, founded in the 13th century by Hazrat Kazi Syed Tajuddin, carrying exquisite Persian woodwork and architectural heritage.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'Kazimar Street, Periyar, Madurai', 9.913, 78.113, '5:00 AM - 9:30 PM', 'Free', 4.7),
(45, 4, 'Athisayam Water Theme Park', 'Sprawling 70-acre water and amusement theme park with high-speed roller-coasters, water slides, lazy rivers, wave pools, and scientific entertainment.', 'Entertainment', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800', 'Madurai-Dindigul Road, Paravai, Madurai', 9.988, 78.082, '10:00 AM - 6:30 PM', '₹700', 4.6),
(46, 4, 'Puthu Mandapam Ancient Craft & Textile Bazaar', 'A 400-year-old pillared stone pavilion opposite Meenakshi Temple''s East Tower, bustling with master tailors, brass artisans, wooden toy craftsmen, and cotton weavers.', 'Shopping', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', 'Opposite East Tower, Meenakshi Amman Temple, Madurai', 9.919, 78.121, '9:00 AM - 9:30 PM', 'Free', 4.8),
(47, 4, 'Goripalayam Dargah', 'A prominent 13th-century twin-tomb shrine situated on the northern bank of Vaigai River, known for its massive 70-foot single stone dome and harmonious festive traditions.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'Chithirai Street, Goripalayam, Madurai', 9.931, 78.128, '6:00 AM - 9:00 PM', 'Free', 4.7),
(48, 4, 'St. Mary''s Cathedral Church', 'One of the oldest Catholic churches in India established in 1840, presenting a magnificent fusion of European Roman and continental Gothic bell towers.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'East Veli Street, Madurai', 9.917, 78.126, '6:00 AM - 8:30 PM', 'Free', 4.6),
(49, 5, 'Yercaud Lake & Emerald Valley', 'Picturesque jewel nestled in the Shevaroy Hills at 4,970 feet, surrounded by lush gardens, pedal boats, and cool misty mountain breezes.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Yercaud Town, Shevaroy Hills, Salem District', 11.7753, 78.2093, '9:00 AM - 5:30 PM', '₹30', 4.7),
(50, 5, 'Kiliyur Falls & Forest Trek', 'A dramatic 300-foot waterfall cascading into the lush Shervaroyan canyon, approached via a thrilling trek through coffee and citrus orchards.', 'Adventure', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Kiliyur Falls Road, Yercaud, Salem District', 11.793, 78.202, '8:00 AM - 5:00 PM', '₹10', 4.6),
(51, 5, 'Lady''s Seat & Pagoda Point Viewpoints', 'Panoramic rock-face viewpoints offering sweeping eagle-eye vistas of Salem city lights below and winding Ghat hairpin curves.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Lady''s Seat Road, Yercaud, Salem District', 11.768, 78.204, '7:00 AM - 7:00 PM', '₹20', 4.7),
(52, 5, 'Kurumbapatti Zoological Park', 'Sprawling eco-park located at the foothills of Shevaroy range, sheltering spotted deer, sambar, marsh crocodiles, and colorful avifauna.', 'Nature', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Kurumbapatti, Salem, Tamil Nadu', 11.722, 78.162, '9:00 AM - 5:00 PM (Closed Tuesdays)', '₹25', 4.5),
(53, 5, '1008 Shiva Lingam Hilltop Temple', 'Perched on Ariyanoor Hill, this sacred complex features 1,007 small stone Shiva Lingams symmetrically encircling one colossal main Lingam.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Ariyanoor, NH-47, Salem, Tamil Nadu', 11.602, 78.064, '6:30 AM - 12:30 PM, 4:00 PM - 8:00 PM', 'Free', 4.6),
(54, 5, 'Mettur Dam & Stanley Reservoir Park', 'One of India''s oldest and grandest masonry gravity dams built across Kaveri River in 1934, paired with lush terraced water fountain parks.', 'Historical', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Mettur, Salem District, Tamil Nadu', 11.8, 77.8, '9:00 AM - 5:30 PM', '₹20', 4.7),
(55, 5, 'Kottai Mariamman Historic Temple', 'An ancient 500-year-old sanctum in the heart of Salem Fort, famed for the grand Aadi festival where devotees gather for sacred blessings.', 'Temple', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'I Agraharam, Salem, Tamil Nadu', 11.654, 78.158, '6:00 AM - 12:00 PM, 4:00 PM - 9:00 PM', 'Free', 4.7),
(56, 5, 'Shevaroy Temple & Bear''s Cave', 'The highest peak in Yercaud (5,326 ft) crowned by a cave temple dedicated to Lord Shevaroyan, nearby the mysterious historical Bear''s Cave.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Shevaroy Peak, Yercaud, Salem District', 11.801, 78.225, '6:00 AM - 6:00 PM', 'Free', 4.7),
(57, 5, 'Anna Park & Japanese Silk Garden', 'Lovely landscaped flower park near Yercaud lake featuring Japanese garden architecture, floral topiary, and an orchidarium hosting rare mountain orchids.', 'Nature', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 'Near Yercaud Lake, Salem District', 11.778, 78.21, '9:00 AM - 6:00 PM', '₹20', 4.5),
(58, 5, 'Sankagiri Fort & Hilltop Bastion', 'A monumental 15th-century Vijayanagara hilltop fortress featuring 14 defensive rampart walls, weapons vaults, and historic prison chambers.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Sankagiri, Salem District', 11.482, 77.869, '7:00 AM - 5:30 PM', 'Free', 4.6),
(59, 5, 'Sugavaneswarar Temple', 'Ancient Shiva temple situated in the heart of Salem, believed to have been worshiped by Sage Suka Brahmarishi with sacred parrot inscriptions.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Center Town, Salem', 11.658, 78.156, '6:00 AM - 12:30 PM, 4:30 PM - 8:30 PM', 'Free', 4.7),
(60, 5, 'Pagoda Point & Raja Rajeshwari Temple', 'Scenic ridge outlook adorned with four ancient pyramid stone piles constructed by local tribes, providing stunning valley views of Harur plains.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Eastern Slopes, Yercaud, Salem District', 11.776, 78.228, '6:30 AM - 6:30 PM', '₹15', 4.6),
(61, 6, 'Lalbagh Botanical Gardens & Glass House', 'Commissioned in 1760 by Hyder Ali and completed by Tipu Sultan, this 240-acre botanical haven features the iconic London Crystal Palace-modeled Glass House.', 'Nature', 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?w=800', 'Mavalli, Bengaluru, Karnataka', 12.9507, 77.5848, '6:00 AM - 7:00 PM', '₹30', 4.8),
(62, 6, 'Bangalore Tudor Palace & Grounds', 'Built in 1878 by Chamarajendra Wadiyar X in Tudor Revival style, adorned with fortified towers, woodcarvings, Victorian stained glass, and royal hunting trophies.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Vasanth Nagar, Bengaluru, Karnataka', 12.9988, 77.5921, '10:00 AM - 5:30 PM', '₹250', 4.7),
(63, 6, 'Wonderla Amusement & Water Park', 'India''s top-rated mega amusement park featuring 60+ world-class high-thrill rides, solar-heated wave pools, reverse roller-coasters, and sky wheels.', 'Entertainment', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800', '28th km, Mysore Road, Bengaluru, Karnataka', 12.8343, 77.4011, '11:00 AM - 6:00 PM (Weekdays), 11:00 AM - 7:00 PM (Weekends)', '₹1350', 4.9),
(64, 6, 'Cubbon Park & Attara Kacheri', 'Sprawling 300-acre green lung in central Bangalore established in 1870, home to bamboo thickets, colonial statues, and the neo-classical red Attara Kacheri.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Kasturba Road, Bengaluru, Karnataka', 12.9763, 77.5929, '6:00 AM - 8:00 PM', 'Free', 4.7),
(65, 6, 'Bannerghatta Biological Safari & Butterfly Park', 'Premier 25,000-acre biological reserve offering AC bus safaris to observe tigers, lions, and bears roaming freely, alongside India''s first enclosed tropical Butterfly Park.', 'Adventure', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Bannerghatta Main Rd, Bengaluru, Karnataka', 12.8009, 77.5777, '9:30 AM - 5:00 PM (Closed Tuesdays)', '₹350', 4.7),
(66, 6, 'Tipu Sultan''s Summer Palace & Bangalore Fort', 'Exquisite two-story Indo-Islamic teakwood palace built entirely of carved wood pillars, arches, and balconies, accompanied by the stone ramparts of Bangalore Fort.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Albert Victor Road, Chamrajpet, Bengaluru', 12.9593, 77.5737, '8:30 AM - 5:30 PM', '₹20', 4.6),
(67, 6, 'Visvesvaraya Industrial & Technological Museum', 'Interactive science wonder honoring Sir M. Visvesvaraya, with hands-on engines, biotechnology labs, 3D space theater, and life-size animated dinosaurs.', 'Museum', 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=800', 'Kasturba Road, Cubbon Park, Bengaluru', 12.9752, 77.5963, '9:30 AM - 6:00 PM', '₹85', 4.8),
(68, 6, 'ISKCON Temple Bangalore (Sri Radha Krishna-chandra)', 'Colossal neo-classical cultural shrine situated on Hare Krishna Hill, combining glass-and-brass temple towers with spiritual meditation halls and prasadam feasts.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Hare Krishna Hill, Rajajinagar, Bengaluru', 13.0098, 77.5511, '4:15 AM - 5:00 AM, 7:15 AM - 1:00 PM, 4:15 PM - 8:30 PM', 'Free', 4.8),
(69, 6, 'UB City Sky Lounge & Art Pavilion', 'India''s first luxury commercial mall and skyscraper hub, hosting upscale global boutiques, contemporary rooftop dining, and open-air art amphitheatres.', 'Shopping', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', '24 Vittal Mallya Road, Bengaluru', 12.9719, 77.5958, '10:30 AM - 11:30 PM', 'Free', 4.8),
(70, 6, 'National Gallery of Modern Art (NGMA)', 'Housed in the historic Manikyavelu Mansion surrounded by lotus ponds, displaying masterworks of Raja Ravi Varma, Amrita Sher-Gil, and Rabindranath Tagore.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', '49 Palace Road, Bengaluru', 12.989, 77.588, '10:00 AM - 6:00 PM (Closed Mondays)', '₹20', 4.7),
(71, 6, 'Commercial Street & Russell Market', 'Bengaluru''s most vibrant bustling shopping artery, famous for silk, pashminas, artisanal jewelry, and the colonial heritage Russell Market.', 'Shopping', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', 'Tasker Town, Shivaji Nagar, Bengaluru', 12.982, 77.608, '10:30 AM - 9:30 PM', 'Free', 4.6),
(72, 6, 'Ulsoor Lake & Boating Promenade', 'Sprawling 120-acre urban lake established by Kempe Gowda II, adorned with green islets, boat cruises, and paved morning walking boulevards.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Halasuru, Bengaluru', 12.983, 77.62, '6:00 AM - 8:00 PM (Boating till 6 PM)', 'Free', 4.6),
(73, 7, 'Kodaikanal Lake & Star-Shaped Promenade', 'A magnificent star-shaped artificial lake built in 1863 spanning 60 acres, fringed by weeping willows, rowboats, pedal craft, and horse trails.', 'Nature', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800', 'Lake Road, Kodaikanal, Tamil Nadu', 10.233, 77.49, '6:00 AM - 6:30 PM', '₹30', 4.8),
(74, 7, 'Coaker''s Walk & Cloud Viewpoint', 'A 1-kilometer pedestrian mountain path constructed in 1872 on steep valley slopes, offering surreal views of drifting clouds and the plains of Madurai.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Coakers Walk, Kodaikanal, Tamil Nadu', 10.231, 77.497, '7:00 AM - 7:00 PM', '₹30', 4.7),
(75, 7, 'Pillar Rocks & Guna Caves', 'Three giant granite rock boulders soaring 400 feet vertically into mountain clouds, overlooking misty chasms and deep cavernous geological crevices.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Pillar Rocks Rd, Kodaikanal, Tamil Nadu', 10.21, 77.468, '9:00 AM - 5:00 PM', '₹20', 4.7),
(76, 7, 'Bryant Park & Botanical Glasshouse', 'Manicured 20-acre botanical showcase established in 1908 by H.D. Bryant, featuring hybrid rose beds, a historic Bodhi tree, and annual horticultural festivals.', 'Nature', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 'Lower Shola Rd, Kodaikanal, Tamil Nadu', 10.234, 77.495, '9:00 AM - 6:00 PM', '₹30', 4.6),
(77, 7, 'Silver Cascade Falls', 'A roaring 180-foot waterfall formed by the outflow of Kodai Lake, cascading over sleek black granite cliffs right along the mountain Ghat road.', 'Nature', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Kodaikanal Ghat Road, Tamil Nadu', 10.245, 77.518, 'Open 24/7', 'Free', 4.5),
(78, 7, 'Pine Forest & Shola Woods', 'Century-old British pine woodlands cultivated in 1906 by Mr. Bryant. Needle-cushioned terrain surrounded by soaring straight trunks and atmospheric mountain mist.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Pine Forest Road, Kodaikanal', 10.218, 77.472, '8:30 AM - 6:00 PM', '₹20', 4.8),
(79, 7, 'Dolphin''s Nose & Echo Rock (Vattakanal)', 'A natural flat rock protrusion jutting out over a 6,600-foot precipice in the hippie enclave of Vattakanal. Unsurpassed views of gorges and distant villages.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Vattakanal Trail, Kodaikanal', 10.215, 77.498, '6:00 AM - 5:30 PM', '₹20', 4.8),
(80, 7, 'Chettiar Park & Kurinji Andavar Temple', 'Famous hilltop shrine dedicated to Lord Murugan, celebrated as the epicenter of the mythical Kurinji flower that blossoms once every 12 years across the valley.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Kurinji Andavar Temple Road, Kodaikanal', 10.252, 77.502, '7:00 AM - 7:00 PM', 'Free', 4.6)
INSERT INTO public.places (id, city_id, name, description, category, image_url, address, latitude, longitude, opening_hours, entry_fee, rating) VALUES
(81, 7, 'Mannavanur Eco-Lake & Sheep Farm', 'A serene alpine farming meadow situated 35 km from town. Rolling green hills grazing high-altitude sheep, pine woods, and a quiet lake with coracle boating.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Mannavanur Village, Kodaikanal Hills', 10.285, 77.35, '9:00 AM - 5:00 PM', '₹50', 4.8),
(82, 7, 'Bear Shola Falls', 'A tranquil secluded forest waterfall tucked inside a reserve valley where bears once drank. Pristine cascades surrounded by wild ferns and rocky trails.', 'Nature', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Bear Shola Road, Kodaikanal', 10.241, 77.483, '10:00 AM - 5:00 PM', 'Free', 4.5),
(83, 7, 'Solar Observatory & Astronomy Museum', 'Founded in 1899 at the highest point of Kodai (7,700 ft). Houses solar telescopes, an astronomy library, and solar physics exhibits that discovered the Evershed effect.', 'Museum', 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=800', 'Observatory Road, Kodaikanal', 10.232, 77.465, '10:00 AM - 12:00 PM, 2:00 PM - 4:00 PM', '₹50', 4.7),
(84, 7, 'Moir Point Viewpoint', 'Historical viewpoint named after Sir Thomas Moir, marking the entrance to Berijam Lake road with breathtaking vistas over green valleys and sheer granite cliffs.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Berijam Road, Kodaikanal', 10.211, 77.458, '9:00 AM - 5:00 PM', '₹20', 4.6),
(85, 8, 'Promenade Beach & Goubert Avenue', 'The iconic 1.5-km seaside boulevard of French Quarter, closed to motorized traffic in the evening, flanked by colonial statues, French villas, and rolling blue waves.', 'Beach', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Goubert Ave, White Town, Puducherry', 11.9338, 79.8359, 'Open 24/7 (Promenade walking hours 5 PM - 6 AM)', 'Free', 4.8),
(86, 8, 'Auroville & Golden Matrimandir', 'An experimental international township dedicated to human unity, crowned by the colossal gold-plated sphere Matrimandir and its silent crystal meditation chamber.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Auroville, Viluppuram District / Puducherry', 12.007, 79.8107, '9:00 AM - 5:30 PM (Passes required for inner chamber)', 'Free', 4.9),
(87, 8, 'Sri Aurobindo Ashram', 'Spiritual sanctum founded in 1926 by Sri Aurobindo and Mirra Alfassa (The Mother), preserving their floral samadhi in a serene tree-shaded marble courtyard.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Rue de la Marine, White Town, Puducherry', 11.9366, 79.8347, '8:00 AM - 12:00 PM, 2:00 PM - 6:00 PM', 'Free', 4.8),
(88, 8, 'Paradise Beach & Chunnambar Ferry', 'An isolated golden sand spit accessible solely via a scenic 15-minute backwater boat cruise along the Chunnambar river, boasting pristine waves and water sports.', 'Beach', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Chunnambar, Nonankuppam, Puducherry', 11.875, 79.808, '9:00 AM - 5:00 PM', '₹350', 4.7),
(89, 8, 'French War Memorial & White Town Quarter', 'Graceful memorial honoring French soldiers of World War I, nestled amidst French colonial boulevards lined with pastel-yellow villas, wrought iron balconies, and bistros.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Goubert Ave, White Town, Puducherry', 11.932, 79.835, '10:00 AM - 5:00 PM', 'Free', 4.7),
(90, 8, 'Serenity Beach & Surfing School', 'A crescent-shaped golden beach with gentle blue surf breaks, lined with fishing catamarans, beach shacks, and a premier ISA-certified surfing academy.', 'Beach', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Kottakuppam, East Coast Road, Pondicherry', 11.968, 79.845, 'Open 24/7', 'Free', 4.7),
(91, 8, 'Botanical Garden & Heritage Toy Train', 'Established in 1826 by French botanist C.S. Perrottet over 22 green acres. Features grand French garden layouts, exotic flora from across the globe, and a mini toy train.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Subbaiah Salai, Puducherry', 11.928, 79.824, '9:00 AM - 6:00 PM', '₹20', 4.6),
(92, 8, 'Basilica of the Sacred Heart of Jesus', 'Stunning neo-Gothic Catholic basilica constructed in 1907 by French missionaries. Famed for its towering twin steeples, rare stained-glass depictions, and Corinthian pillars.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'South Boulevard, Puducherry', 11.926, 79.828, '6:00 AM - 8:30 PM', 'Free', 4.8),
(93, 8, 'Chunnambar Boat House & Mangrove Lagoons', 'Picturesque backwater complex where the Chunnambar River meets the Bay of Bengal. Offers pedal boating, motorized mangrove cruises, and treehouse retreats.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Chunnambar, Cuddalore Road, Puducherry', 11.879, 79.805, '9:00 AM - 5:30 PM', '₹50', 4.6),
(94, 8, 'Pondicherry Museum & Sculptures Gallery', 'Housed in the historic Law de Lauriston building, showcasing Roman amphorae excavated from ancient Arikamedu, French royal carriages, and bronze Chola sculptures.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Saint Louis Street, White Town, Puducherry', 11.934, 79.834, '9:00 AM - 5:00 PM (Closed Mondays)', '₹20', 4.6),
(95, 8, 'Arikamedu Roman-Indian Port Site', 'Ancient 2nd-century BC Indo-Roman trade port where Roman pottery, beads, glassware, and wine amphorae were excavated, proving deep Greco-Roman trade ties.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Ariyankuppam Riverbank, Puducherry', 11.898, 79.823, '9:00 AM - 5:00 PM', 'Free', 4.5),
(96, 8, 'Auroville Matrimandir Viewing Point & Gardens', 'The open serene amphitheatre and viewing pavilion surrounded by 12 manicured petals and tranquil shaded gardens offering contemplative vistas of the Golden Matrimandir.', 'Nature', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Auroville Central Enclave', 12.006, 79.812, '9:00 AM - 4:30 PM', 'Free', 4.8),
(97, 9, 'Vivekananda Rock Memorial & Ferry', 'A sacred monument erected in 1970 on two granite rock islets 500 meters offshore where Swami Vivekananda attained enlightenment after 3 days of deep meditation in 1892.', 'Historical', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Vivekanandapuram Offshore, Kanyakumari, Tamil Nadu', 8.078, 77.555, '8:00 AM - 4:00 PM (Ferry operations subject to tide)', '₹75', 4.9),
(98, 9, 'Thiruvalluvar 133-ft Stone Statue', 'A colossal 133-foot granite statue honoring immortal Tamil saint-poet Thiruvalluvar, standing tall amidst crashing ocean waves, symbolizing the 133 chapters of the Tirukkural.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Offshore Island, Kanyakumari, Tamil Nadu', 8.077, 77.556, '8:00 AM - 4:00 PM (Accessible via Rock Memorial ferry)', 'Free', 4.8),
(99, 9, 'Kanyakumari Beach & Triveni Sangam', 'The sacred geographic confluence where the Indian Ocean, Arabian Sea, and Bay of Bengal converge, famed worldwide for simultaneous sunrise and sunset spectacles.', 'Beach', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Beach Road, Kanyakumari, Tamil Nadu', 8.08, 77.553, 'Open 24/7', 'Free', 4.7),
(100, 9, 'Padmanabhapuram Palace', 'A magnificent 16th-century wooden palace of the Travancore Kings, boasting intricately carved rosewood ceilings, mica windows, Chinese carved thrones, and secret tunnels.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Thuckalay, Kanyakumari District, Tamil Nadu', 8.2508, 77.3275, '9:00 AM - 4:30 PM (Closed Mondays)', '₹50', 4.8),
(101, 9, 'Bhagavathy Amman Temple', 'A 3,000-year-old historic coastal shrine dedicated to virgin Goddess Kanya Kumari, renowned for the brilliant ruby nose-ring of the deity that illuminated passing ships.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Temple Street, Kanyakumari, Tamil Nadu', 8.0815, 77.554, '4:30 AM - 12:30 PM, 4:00 PM - 8:30 PM', 'Free', 4.8),
(102, 9, 'Sunset Point & Hidden Beach', 'Scenic sandy beach enclave located 2 km southwest of town, offering uninterrupted wide horizons to witness the sun sinking into the Arabian Sea.', 'Nature', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Kovalam Road, Kanyakumari', 8.083, 77.535, 'Open 24/7', 'Free', 4.7),
(103, 9, 'Gandhi Memorial Mandapam', 'Built in Orissa temple style on the spot where Mahatma Gandhi''s ashes were placed before immersion. On his birthday (Oct 2), sunrays pass through a ceiling aperture onto the pedestal.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Sea Shore, Kanyakumari', 8.081, 77.552, '7:00 AM - 7:00 PM', '₹10', 4.6),
(104, 9, 'Vattakottai Fort (Circular Sea Fort)', 'An 18th-century seaside granite coastal fort constructed under the Travancore Kingdom by Dutch naval officer Eustachius De Lannoy, with cannon ramps overlooking crashing waves.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Vattakottai, Kanyakumari District', 8.125, 77.565, '8:00 AM - 5:30 PM', '₹25', 4.7),
(105, 9, 'Our Lady of Ransom Church', 'A soaring 100-year-old Portuguese Gothic cathedral on the beach with 153-foot golden-cross towers, colorful stained glass, and illuminated nighttime facades.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'Church Road, Kanyakumari', 8.082, 77.551, '5:30 AM - 8:30 PM', 'Free', 4.7),
(106, 9, 'Thirparappu Waterfalls & Temple', 'Picturesque river waterfalls formed by the Kodayar River tumbling over 50 feet of rocky bed into a natural bathing basin, flanked by a 9th-century Shiva temple.', 'Nature', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Thirparappu, Kanyakumari District', 8.385, 77.265, '7:00 AM - 6:00 PM', '₹20', 4.6),
(107, 9, 'Baywatch Amusement & Water Park', 'A premier family water amusement park on Kanyakumari-Trivandrum Highway, featuring India''s first complete wax museum, giant wheel, and wave splash pools.', 'Entertainment', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800', 'NH 44, Kovalam Road, Kanyakumari', 8.095, 77.54, '10:00 AM - 6:30 PM', '₹550', 4.5),
(108, 9, 'Chothavilai Beach & Sand Dunes', 'One of the longest pristine beaches in Tamil Nadu, with clean white sand dunes, coastal pine groves, and shallow turquoise waters ideal for ocean wading.', 'Nature', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Chothavilai, Kanyakumari District', 8.132, 77.485, 'Open 24/7', 'Free', 4.6),
(109, 10, 'Brihadeeswara Temple (Big Temple)', 'The undisputed masterpiece of Chola architecture built in 1010 AD by Raja Raja Chola I. Features a 216-foot granite Vimana crowned by an 80-ton single-stone dome.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Membalam Rd, Balaganapathy Nagar, Thanjavur, Tamil Nadu', 10.7828, 79.1318, '6:00 AM - 12:30 PM, 4:00 PM - 8:30 PM', 'Free', 4.9),
(110, 10, 'Thanjavur Maratha Palace & Bell Tower', 'An imposing palace complex constructed by Nayak rulers and enhanced by Maratha kings. Features seven-story observation Bell Tower and the ornate Durbar Hall.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'East Main St, Thanjavur, Tamil Nadu', 10.7925, 79.137, '9:00 AM - 6:00 PM', '₹50', 4.7),
(111, 10, 'Saraswathi Mahal Library & Museum', 'One of the oldest medieval libraries in Asia, housing over 60,000 rare palm-leaf manuscripts written in Sanskrit, Tamil, Marathi, and Telugu.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Inside Palace Complex, Thanjavur, Tamil Nadu', 10.7928, 79.1365, '10:00 AM - 1:00 PM, 1:30 PM - 5:30 PM (Closed Wednesdays)', '₹30', 4.8),
(112, 10, 'Sangeetha Mahal (Hall of Music)', 'An acoustically perfect music auditorium built during the 16th century by Sevappa Nayak inside the palace complex, featuring vaulted ceilings and cooling water pools.', 'Historical', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Palace Complex, Thanjavur, Tamil Nadu', 10.792, 79.136, '9:00 AM - 5:30 PM', '₹20', 4.6),
(113, 10, 'Sivaganga Park & Chola Moat Gardens', 'A recreational garden dating back to Raja Serfoji, located adjacent to the Big Temple moat with tranquil motorboating, aviary, and flower gardens.', 'Nature', 'https://images.unsplash.com/photo-1448375240586-882707db888b?w=800', 'Near Big Temple, Thanjavur, Tamil Nadu', 10.785, 79.13, '9:00 AM - 6:00 PM', '₹20', 4.5),
(114, 10, 'Royal Palace Art Gallery & Bronze Sculptures', 'Magnificent gallery situated in the Palace Durbar Hall exhibiting priceless Chola-era bronze icons including Nataraja, Parvathi, and Stone statues of Chola Kings.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Palace Complex, East Main Street, Thanjavur', 10.793, 79.1375, '9:00 AM - 6:00 PM', '₹50', 4.8),
(115, 10, 'Schwartz Church & British Memorial', 'Built in 1779 by Danish missionary Rev. Christian Friedrich Schwartz with the patronage of Raja Serfoji II. Features a touchingly sculpted marble relief by John Flaxman.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'Near Shiva Ganga Tank, Thanjavur', 10.784, 79.131, '8:00 AM - 5:30 PM', 'Free', 4.6),
(116, 10, 'Grand Anicut (Kallanai Dam)', 'The world''s fourth-oldest water diversion dam, built in the 2nd century AD by King Karikala Chola across the Kaveri. A living tribute to ancient Tamil hydraulic engineering.', 'Historical', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Kallanai, Kaveri-Kollidam Confluence, Thanjavur District', 10.835, 78.818, '8:00 AM - 6:30 PM', '₹10', 4.8),
(117, 10, 'Punnainallur Mariamman Temple', 'A revered 17th-century temple established by the Maratha King Venkoji Maharaja, famed for the swayambhu anthill deity that transforms with natural moisture.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Punnainallur, Thanjavur District', 10.788, 79.185, '6:00 AM - 1:00 PM, 4:00 PM - 9:00 PM', 'Free', 4.7),
(118, 10, 'Thanjavur Art & Doll Weaving Village', 'Traditional artisan quarters where generations of craftsmen create the world-famous dancing bobblehead dolls (Thanjavur Gundu Bommai) and 22-carat gold foil Tanjore paintings.', 'Shopping', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', 'West Main Street & Manojappa Street, Thanjavur', 10.789, 79.133, '9:30 AM - 8:30 PM', 'Free', 4.8),
(119, 10, 'Bangaru Kamakshi Amman Temple', 'Historic shrine housing the famed Golden Kamakshi deity brought from Kanchipuram to Thanjavur during the 18th-century Carnatic wars for divine safekeeping.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'West Main Street, Thanjavur', 10.787, 79.134, '6:00 AM - 12:00 PM, 4:30 PM - 8:30 PM', 'Free', 4.7),
(120, 10, 'Thiruvalanjuli Sweta Vinayagar Temple', 'Ancient temple near Kumbakonam famed for its white seashell-sculpted Vinayagar idol, intricate stone lattice windows, and towering Chola architecture.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Thiruvalanjuli, Thanjavur-Kumbakonam Road', 10.932, 79.332, '6:30 AM - 12:30 PM, 4:00 PM - 8:30 PM', 'Free', 4.7)
INSERT INTO public.places (id, city_id, name, description, category, image_url, address, latitude, longitude, opening_hours, entry_fee, rating) VALUES
(121, 11, 'Mysore Royal Palace (Amba Vilas)', 'The grand Indo-Saracenic royal seat of the Wadiyar dynasty. Boasts a Golden Throne, stained-glass peacock ceilings, and 97,000 bulbs that illuminate on Sunday evenings.', 'Historical', 'https://images.unsplash.com/photo-1596176530529-78163a4f7af2?w=800', 'Sayyaji Rao Rd, Agrahara, Chamrajpura, Mysuru', 12.3052, 76.6552, '10:00 AM - 5:30 PM (Illumination on Sundays 7:00 PM - 7:45 PM)', '₹100', 4.9),
(122, 11, 'Chamundeshwari Temple & Chamundi Hill', 'Perched at 3,300 feet atop Chamundi Hill, this sacred 1,000-year-old temple honors Goddess Chamundeshwari, with a monumental 16-foot monolithic Nandi bull.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Chamundi Hill, Mysuru, Karnataka', 12.2725, 76.671, '7:30 AM - 2:00 PM, 3:30 PM - 6:00 PM, 7:30 PM - 9:00 PM', 'Free', 4.8),
(123, 11, 'Brindavan Gardens & Musical Fountain', 'Sprawling terraced Mughal gardens laid out behind the Krishnaraja Sagara Dam, featuring illuminated dancing fountains synchronized to classical and popular music.', 'Nature', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 'KRS Dam, Mandya / Mysuru District, Karnataka', 12.423, 76.573, '6:30 AM - 9:00 PM (Musical Fountain 6:30 PM - 8:00 PM)', '₹50', 4.7),
(124, 11, 'Sri Chamarajendra Zoological Gardens (Mysore Zoo)', 'Established in 1892 by Maharaja Chamaraja Wadiyar over 157 acres, one of the oldest and best-kept zoos in India, home to giraffes, elephants, gorillas, and white tigers.', 'Nature', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Zoo Main Rd, Indira Nagar, Ittige Gudu, Mysuru', 12.3023, 76.6644, '8:30 AM - 5:30 PM (Closed Tuesdays)', '₹100', 4.8),
(125, 11, 'St. Philomena''s Neo-Gothic Cathedral', 'A monumental neo-Gothic Catholic cathedral built in 1936 with 175-foot twin spires modeled after Germany''s Cologne Cathedral, housing third-century relics of St. Philomena.', 'Historical', 'https://images.unsplash.com/photo-1548625361-195feee13d80?w=800', 'Lashkar Mohalla, Mysuru, Karnataka', 12.321, 76.658, '5:00 AM - 6:00 PM', 'Free', 4.7),
(126, 11, 'Jaganmohan Palace & Art Gallery', 'Built in 1861 as an alternate royal residence, this palace now houses the Sri Jayachamarajendra Art Gallery with original masterpieces by Raja Ravi Varma and musical clocks.', 'Museum', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Deshika Road, Subbarayanakere, Mysuru', 12.308, 76.65, '8:30 AM - 5:30 PM', '₹75', 4.8),
(127, 11, 'Karanji Lake & Walk-Through Aviary', 'Sprawling 90-acre nature park boasting India''s largest walk-through aviary, butterfly park, and serene lake waters surrounded by migrating pelicans and painted storks.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Siddartha Layout, Mysuru', 12.302, 76.674, '8:30 AM - 5:30 PM (Closed Tuesdays)', '₹50', 4.7),
(128, 11, 'Railway Museum Mysuru', 'India''s second oldest railway heritage museum, preserving the royal 1899 Mysore Maharani salon coach, vintage Austin rail cars, and steam locomotives.', 'Museum', 'https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=800', 'KRS Road, Medar Block, Yadavagiri, Mysuru', 12.316, 76.643, '10:00 AM - 5:30 PM (Closed Mondays)', '₹50', 4.7),
(129, 11, 'Devaraja 130-Year-Old Royal Market', 'A sensory extravaganza operating since the reign of Chamaraja Wadiyar IX, packed with fresh mounds of fragrant marigolds, Mysore betel leaves, pure sandalwood, and incense.', 'Shopping', 'https://images.unsplash.com/photo-1567401893414-76b7b1e5a7a5?w=800', 'Sayyaji Rao Road, Mysuru', 12.309, 76.652, '6:30 AM - 9:30 PM', 'Free', 4.8),
(130, 11, 'Ranganathittu Bird Sanctuary', 'The largest bird sanctuary in Karnataka, comprising six tranquil islets on Kaveri River. Guided boat rides pass marsh crocodiles, spoonbills, and thousands of nesting herons.', 'Adventure', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Srirangapatna, Mandya / Mysuru Highway', 12.424, 76.694, '8:30 AM - 5:30 PM', '₹80', 4.8),
(131, 11, 'Venugopala Swamy Temple (KRS Backwaters)', 'Stunning 12th-century Hoysala temple originally submerged under the KRS reservoir for decades, painstakingly restored block-by-block on the picturesque water edge of Hosa Kannambadi.', 'Temple', 'https://images.unsplash.com/photo-1609766857041-ed402ea8069a?w=800', 'Hosa Kannambadi, KRS Backwaters, Mysuru', 12.441, 76.548, '9:00 AM - 6:00 PM', 'Free', 4.8),
(132, 11, 'GRS Fantasy Theme & Water Park', 'Premier amusement water park in Metagalli featuring the Columbia pendulum swing, Amazon thrill rapids, aqua danceloop, and children''s splash pool.', 'Entertainment', 'https://images.unsplash.com/photo-1513836279014-a89f7a76ae86?w=800', 'KRS Road, Metagalli, Mysuru', 12.355, 76.625, '10:30 AM - 6:00 PM', '₹850', 4.6),
(133, 12, 'Eravikulam National Park & Nilgiri Tahr', 'Kerala''s first national park nestled along the crest of Western Ghats, sheltering the largest surviving wild population of endangered Nilgiri Tahr against rolling rolling Shola grass.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Kannandevan Hills, Munnar, Kerala', 10.15, 77.06, '7:30 AM - 4:00 PM (Closed Feb-March for calving)', '₹200', 4.9),
(134, 12, 'Mattupetty Dam & Speedboating', 'A concrete gravity dam built in 1953 surrounded by tea slopes, renowned for speedboating across deep mountain waters and wild elephant herds visiting the banks.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Mattupetty, Munnar, Kerala', 10.105, 77.125, '9:30 AM - 5:00 PM', '₹50', 4.7),
(135, 12, 'Tata Tea Museum & Nallathanni Estate', 'Preserving century-old tea machinery, the original 1905 rotorvane roller, and manual tea plucking demonstrations with curated tea-tasting sessions.', 'Museum', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800', 'KDHP House, Nallathanni Estate, Munnar', 10.089, 77.054, '9:00 AM - 5:00 PM (Closed Mondays)', '₹125', 4.7),
(136, 12, 'Top Station & Cloud Valley Panorama', 'The highest point on Munnar-Kodaikanal road (6,170 ft) on the Kerala-Tamil Nadu border, offering breathtaking vistas of Kurinjimala sanctuary and the Western Ghats.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Top Station, Kerala-Tamil Nadu Border', 10.124, 77.243, '6:00 AM - 6:00 PM', '₹25', 4.8),
(137, 12, 'Attukad Waterfalls & Forest Trail', 'A roaring mountain waterfall set in a secluded forest gorge between Munnar and Pallivasal, surrounded by jungle greenery and wooden footbridges.', 'Nature', 'https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?w=800', 'Attukad Falls Rd, Pallivasal, Munnar', 10.052, 77.045, 'Open 24/7', 'Free', 4.7),
(138, 12, 'Kundala Lake & Arch Dam Boating', 'Asia''s first arched dam framed by silent pine and eucalyptus woods, where Kashmiri-style Shikara boat cruises and pedal boats glide over shimmering waters.', 'Nature', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Kundala Valley, Munnar-Top Station Rd', 10.118, 77.168, '9:00 AM - 5:00 PM', '₹50', 4.8),
(139, 12, 'Anamudi Peak Viewpoint', 'Rising to 8,842 feet, the ''Everest of South India''. While the summit is protected for wildlife, viewpoint decks offer stunning panoramas of the colossal granite peak.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Eravikulam National Park, Munnar', 10.169, 77.064, '7:30 AM - 4:00 PM', 'Free', 4.9),
(140, 12, 'Pothamedu Viewpoint', 'Panoramic mountain cliff vantage offering dramatic sweeps of verdant tea, coffee, and cardamom plantations blanketed in shifting blankets of fog.', 'Nature', 'https://images.unsplash.com/photo-1589182373726-e4f658ab50f0?w=800', 'Pothamedu, Munnar', 10.058, 77.051, '6:00 AM - 7:00 PM', 'Free', 4.7),
(141, 12, 'Blossom International Eco Park', 'A peaceful 16-acre eco-adventure park near the Muthirapuzha River with rare exotic flowers, treehouses, roller skating rinks, ziplining, and cycling trails.', 'Nature', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?w=800', 'Aluva - Munnar Road, Near Headworks Dam', 10.071, 77.059, '9:00 AM - 7:00 PM', '₹40', 4.6),
(142, 12, 'Lockhart Gap & Chokramudi Trek', 'A spectacular natural rock cleft resembling a heart shape between two cliffs. Renowned for mist-filled sunset trekking trails and spice plantation views.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Lockhart Gap, Munnar-Thekkady Road', 10.04, 77.1, '6:00 AM - 6:30 PM', 'Free', 4.7),
(143, 12, 'Kolukkumalai Highest Tea Estate', 'The highest organic orthodox tea estate in the world at 7,900 feet, approached via thrilling 4x4 off-road jeep climbs above endless cloud oceans.', 'Adventure', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Kottagudi / Kolukkumalai Hills, Near Munnar', 10.082, 77.228, 'Jeep safari departs 4:30 AM for sunrise', '₹150', 4.9),
(144, 12, 'Chinnar Wildlife Sanctuary & Dolmens', 'A rain-shadow deciduous wildlife park home to the vulnerable grizzled giant squirrel, star tortoises, and prehistoric Megalithic burial dolmens.', 'Adventure', 'https://images.unsplash.com/photo-1534567153574-2b12153a87f0?w=800', 'Munnar - Udumalpet Road, Marayoor Range', 10.315, 77.195, '7:00 AM - 5:00 PM', '₹100', 4.7),
(145, 1, 'Pollachi Coconut Groves & Village Farmstay', 'An idyllic countryside paradise famous for endless green coconut canopies, tranquil irrigation canals, traditional bullock-cart rides, jaggery processing sheds, and organic agro-farms.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Anamalai Foothills, Pollachi Countryside, Coimbatore District', 10.658, 77.008, '6:00 AM - 6:30 PM', 'Free', 4.8),
(146, 1, 'Sethumadai Village & Herbal Agrotour Trails', 'A peaceful farming hamlet at the base of the Western Ghats lined with fragrant nutmeg plantations, cocoa groves, betel-vine trellises, and stream-fed village pathways.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Sethumadai Village, Anaimalai Taluk, Coimbatore District', 10.452, 76.921, '7:00 AM - 6:00 PM', 'Free', 4.7),
(147, 2, 'Muttukadu & Kovalam Coastal Fishing Village', 'A serene coastal fisherman hamlet nestled between backwaters and sea, offering catamaran boat rides with local fishermen, palm-thatched fish drying yards, and village seafood grills.', 'Rural & Village', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Kovalam Coastal Village, ECR, Chennai South', 12.7915, 80.252, '6:00 AM - 7:00 PM', 'Free', 4.6),
(148, 2, 'Kanchipuram Silk Weavers'' Heritage Colony', 'A traditional artisanal weaver settlement where generations of master handloom artisans spin mulberry silk and pure gold zari on ancestral wooden pit-looms in their ancestral village homes.', 'Rural & Village', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Pillaiyarpalayam Weavers Quarter, Kanchipuram Outer', 12.834, 79.703, '9:00 AM - 6:00 PM', 'Free', 4.8),
(149, 3, 'Toda Tribal Hamlet & Sacred Pastoral Reserve', 'An authentic high-altitude settlement of the indigenous Toda community featuring sacred barrel-vaulted thatch huts, conical temples, embroidered poothkuli shawls, and grazing sacred buffaloes.', 'Rural & Village', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800', 'Muthunadu Mund, Wenlock Downs, Nilgiris', 11.432, 76.671, '9:00 AM - 5:30 PM', '₹20', 4.9),
(150, 3, 'Manjoor Valley & Countryside Tea Hamlet', 'A peaceful rural mountain village perched high on the southern slopes of the Nilgiris, surrounded by terraced carrot patches, artisanal mini tea factories, and silent cloud valleys.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Manjoor Village, Kundah Taluk, Nilgiris', 11.233, 76.643, 'Open 24 Hours', 'Free', 4.7),
(151, 4, 'Vilachery Terracotta & Clay Pottery Village', 'A celebrated craft village where skilled potters shape and paint vibrant clay terracotta figurines, temple vahanas, festive dolls, and earthenware using traditional wooden kick-wheels.', 'Rural & Village', 'https://images.unsplash.com/photo-1566127444979-b3d2b654e3d7?w=800', 'Vilachery Village, Pasumalai Outer, Madurai District', 9.882, 78.081, '8:00 AM - 6:30 PM', 'Free', 4.8),
(152, 4, 'Keeladi Ancient Vaigai Agrarian Village', 'A tranquil riverside village on the banks of Vaigai river, internationally famed for archaeological discoveries unearthing an advanced 2,600-year-old Sangam urban civilization amidst coconut groves.', 'Rural & Village', 'https://images.unsplash.com/photo-1548013146-72479768bada?w=800', 'Keeladi Village, Sivaganga Border, Near Madurai', 9.862, 78.188, '9:00 AM - 5:30 PM', '₹15', 4.8),
(153, 5, 'Mallasamudram Handloom Weaving Village', 'A quaint rural textile village famed for organic cotton handloom dhotis, cotton sarees, and rhythmic pit-looms operated in traditional village courtyard homes amidst sugarcane fields.', 'Rural & Village', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Mallasamudram Rural Block, Namakkal-Salem Border', 11.482, 77.962, '8:00 AM - 6:00 PM', 'Free', 4.7),
(154, 5, 'Poiman Karadu & Country Mango Groves', 'A picturesque rural foothill hamlet surrounded by expansive mango orchards, jaggery crushers, and ancient folklore lookouts where rural shepherds graze sheep beneath granite crags.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Poiman Karadu Foothills, Salem Outer', 11.583, 78.118, '6:00 AM - 6:00 PM', 'Free', 4.6),
(155, 6, 'Janapada Loka Folk Arts & Village Heritage', 'A sprawling 15-acre rural lifestyle and folk museum campus featuring traditional village huts, oil extractors, bullock carts, wooden puppets, folk dance arenas, and mud-architecture houses.', 'Rural & Village', 'https://images.unsplash.com/photo-1518998053901-5348d3961a04?w=800', 'Bangalore-Mysore Highway, Ramanagara', 12.721, 77.291, '9:00 AM - 5:30 PM (Closed Tuesday)', '₹50', 4.8),
(156, 6, 'Nrityagram Dance Village & Hesaraghatta Grasslands', 'A visionary eco-rural artists community built using raw mud and red earth bricks, surrounded by rural organic farms, dairy pastures, and tranquil Hesaraghatta freshwater lake.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Hesaraghatta Village, Bengaluru North', 13.161, 77.464, '10:00 AM - 2:00 PM (Closed Mon & Tue)', '₹100', 4.7),
(157, 7, 'Mannavanur Sheep Farm & Pastoral Meadows', 'A pristine alpine village hamlet known for rolling emerald meadows, the central sheep breeding research farm, grazing rabbit warrens, carrot washing canals, and a quiet lake.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Mannavanur Village, Kodaikanal Hills', 10.298, 77.348, '9:00 AM - 5:00 PM', '₹20', 4.8),
(158, 7, 'Poombarai Step-Farming Amphitheatre Village', 'A breathtaking mountain village cascading along steep hill slopes with colorful stepped houses, multi-tiered garlic and cabbage terraces, and the ancient Kuzhanthai Velappar Temple.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Poombarai Village, Kodaikanal Taluk', 10.258, 77.408, 'Open Daily', 'Free', 4.9),
(159, 8, 'Bahour Ancient Paddy Village & Tank', 'Known as the ''Rice Bowl of Puducherry'', an agrarian heritage village famed for 10th-century Chola irrigation reservoirs, sprawling emerald paddy fields, and serene village temples.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Bahour Village, Puducherry South', 11.802, 79.748, 'Open 24 Hours', 'Free', 4.7),
(160, 8, 'Poornankuppam River Village & Mangrove Trails', 'A scenic coastal village settled where backwater rivers meet the Bay of Bengal, surrounded by coconut groves, mangrove estuaries, traditional coracle boats, and fishermen shacks.', 'Rural & Village', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Poornankuppam Village, Near Ariyankuppam', 11.872, 79.808, '6:00 AM - 6:30 PM', 'Free', 4.6)
INSERT INTO public.places (id, city_id, name, description, category, image_url, address, latitude, longitude, opening_hours, entry_fee, rating) VALUES
(161, 9, 'Muttom Seaside Fishing Village & Rock Coast', 'A charming coastal village famed for its hundred-year-old lighthouse perched on rugged granite rocks, colorful wooden fishing catamarans, dry fish racks, and dramatic sea waves.', 'Rural & Village', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=800', 'Muttom Coastal Village, Kanyakumari District', 8.125, 77.318, '6:00 AM - 6:30 PM', '₹10', 4.7),
(162, 9, 'Pechiparai Countryside & Tribal Plantations', 'A lush rural foothill village nestled beside the Pechiparai reservoir, celebrated for sprawling rubber plantations, wild forest honey gatherers, clove groves, and bamboo thickets.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Pechiparai Village, Western Ghats Foothills', 8.452, 77.291, '7:00 AM - 5:30 PM', 'Free', 4.6),
(163, 10, 'Swamimalai Bronze Casting Artisan Village', 'A legendary heritage artisan hamlet where hereditary sthapatis craft world-famous lost-wax process bronze sculptures using age-old formulas codified in ancient Shilpa Shastras.', 'Rural & Village', 'https://images.unsplash.com/photo-1566127444979-b3d2b654e3d7?w=800', 'Swamimalai Village, Near Kumbakonam, Thanjavur District', 10.954, 79.328, '9:00 AM - 6:00 PM', 'Free', 4.9),
(164, 10, 'Thiruvaiyaru Cauvery Agrarian Hamlet', 'A peaceful rural hamlet located on the fertile delta of the Cauvery river, surrounded by lush paddy crops, fragrant plantain groves, and the sacred samadhi of Saint Tyagaraja.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Thiruvaiyaru Village, Thanjavur District', 10.884, 79.103, '6:00 AM - 8:00 PM', 'Free', 4.8),
(165, 11, 'Melukote Heritage Village & Kalyani Tank', 'A sacred rural temple township crowning granite hills, famed for its ancient stepped temple tank (Kalyani), traditional handloom dhotis, Iyengar cuisine, and Sanskrit learning academies.', 'Rural & Village', 'https://images.unsplash.com/photo-1582510003544-4d00b7f74220?w=800', 'Melukote Town, Pandavapura Taluk, Near Mysuru', 12.666, 76.652, '6:30 AM - 8:00 PM', 'Free', 4.8),
(166, 11, 'BR Hills Soliga Tribal Forest Settlement', 'An indigenous hill hamlet in Biligirirangana Hills where the Soliga tribal community maintains sustainable wild honey collecting, organic shade-grown coffee farming, and sacred champak trees.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Biligiriranganatha Swamy Range, Chamarajanagar', 11.995, 77.14, '6:00 AM - 6:00 PM', '₹50', 4.7),
(167, 12, 'Kanthalloor Fruit Orchards & Village Step-Farms', 'A fairytale rural village nestled in a misty rain-shadow valley, celebrated for step-cultivated orchards of apples, plums, oranges, passion fruit, strawberries, and sweet sugarcane jaggery.', 'Rural & Village', 'https://images.unsplash.com/photo-1500382017468-9049fed747ef?w=800', 'Kanthalloor Village, Idukki District', 10.224, 77.198, 'Open Daily', 'Free', 4.9),
(168, 12, 'Marayoor Sugarcane Jaggery & Sandalwood Village', 'A scenic pastoral hamlet renowned for naturally growing wild sandalwood forests, ancient Neolithic dolmens, and traditional open-hearth sugarcane processing sheds making famed Marayoor Sharkara.', 'Rural & Village', 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?w=800', 'Marayoor Countryside, Munnar-Udumalpet Road', 10.281, 77.162, 'Open Daily', 'Free', 4.8)
