-- CITYMATE — Complete Supabase PostgreSQL Schema & Seed Data
-- Your Smart Guide to Every Corner of the City
-- ============================================================================
--
-- HOW TO RUN THIS SCRIPT IN SUPABASE:
-- 1. Log in to your Supabase Dashboard: https://supabase.com/dashboard
-- 2. Select your CityMate project.
-- 3. In the left navigation sidebar, click on "SQL Editor".
-- 4. Click "+ New query".
-- 5. Copy and paste the entire contents of this file into the query editor.
-- 6. Click the "Run" button (or press Ctrl + Enter / Cmd + Enter).
-- 7. You will see "Success. No rows returned" when finished.
-- 8. Navigate to "Table Editor" to verify all tables, rows, and relationships!
-- ============================================================================

-- Enable required PostgreSQL extensions
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- ============================================================================
-- 1. DROP EXISTING TABLES & VIEWS (Clean setup with dependency ordering)
-- ============================================================================
DROP VIEW IF EXISTS public.place_reviews_view CASCADE;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users CASCADE;
DROP FUNCTION IF EXISTS public.handle_new_user() CASCADE;
DROP TRIGGER IF EXISTS on_review_change ON public.reviews CASCADE;
DROP FUNCTION IF EXISTS public.update_place_rating() CASCADE;
DROP FUNCTION IF EXISTS public.is_admin() CASCADE;

DROP TABLE IF EXISTS public.reviews CASCADE;
DROP TABLE IF EXISTS public.favourites CASCADE;
DROP TABLE IF EXISTS public.services CASCADE;
DROP TABLE IF EXISTS public.places CASCADE;
DROP TABLE IF EXISTS public.cities CASCADE;
DROP TABLE IF EXISTS public.admin_users CASCADE;
DROP TABLE IF EXISTS public.profiles CASCADE;

-- ============================================================================
-- 2. TABLE DEFINITIONS
-- ============================================================================

-- A. PROFILES TABLE (References auth.users)
CREATE TABLE public.profiles (
    id UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    full_name TEXT NOT NULL,
    email TEXT,
    avatar_url TEXT DEFAULT 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150',
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.profiles IS 'User profile information synced with Supabase Auth';

-- B. CITIES TABLE
CREATE TABLE public.cities (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    state TEXT NOT NULL,
    country TEXT NOT NULL DEFAULT 'India',
    description TEXT,
    image_url TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.cities IS 'Cities and travel destinations supported by CityMate';

-- C. PLACES TABLE (Tourist Attractions)
CREATE TABLE public.places (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city_id BIGINT NOT NULL REFERENCES public.cities(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    description TEXT,
    category TEXT NOT NULL,
    image_url TEXT,
    address TEXT,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    opening_hours TEXT DEFAULT '09:00 AM - 06:00 PM',
    entry_fee TEXT DEFAULT 'Free',
    rating NUMERIC(3, 2) NOT NULL DEFAULT 4.5 CHECK (rating >= 0 AND rating <= 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.places IS 'Tourist destinations, temples, viewpoints, and cultural spots';

-- D. SERVICES TABLE (Essential City Amenities)
CREATE TABLE public.services (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    city_id BIGINT NOT NULL REFERENCES public.cities(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    service_type TEXT NOT NULL,
    description TEXT,
    address TEXT,
    phone TEXT,
    image_url TEXT,
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    rating NUMERIC(3, 2) NOT NULL DEFAULT 4.5 CHECK (rating >= 0 AND rating <= 5),
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.services IS 'City amenities: Hotels, Restaurants, Hospitals, ATMs, Petrol Bunks, Restrooms, Markets, Bike Rentals, Car Rentals';

-- E. FAVOURITES TABLE
CREATE TABLE public.favourites (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    CONSTRAINT unique_user_place_favourite UNIQUE (user_id, place_id)
);

COMMENT ON TABLE public.favourites IS 'User bookmarked favourite places, preventing duplicates';

-- F. REVIEWS TABLE
CREATE TABLE public.reviews (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    place_id BIGINT NOT NULL REFERENCES public.places(id) ON DELETE CASCADE,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    comment TEXT NOT NULL CHECK (char_length(trim(comment)) > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.reviews IS 'Ratings and comments left by authenticated users on places';

-- G. ADMIN USERS TABLE (Explicit verified admin role for administrative operations)
CREATE TABLE public.admin_users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id UUID NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE,
    role TEXT NOT NULL DEFAULT 'admin',
    created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

COMMENT ON TABLE public.admin_users IS 'Verified platform administrators with privileges to modify places/services';

-- ============================================================================
-- 3. INDEXES FOR PERFORMANCE
-- ============================================================================
CREATE INDEX idx_places_city_id ON public.places(city_id);
CREATE INDEX idx_places_category ON public.places(category);
CREATE INDEX idx_places_name ON public.places(name);

CREATE INDEX idx_services_city_id ON public.services(city_id);
CREATE INDEX idx_services_type ON public.services(service_type);
CREATE INDEX idx_services_name ON public.services(name);

CREATE INDEX idx_favourites_user_id ON public.favourites(user_id);
CREATE INDEX idx_favourites_place_id ON public.favourites(place_id);

CREATE INDEX idx_reviews_place_id ON public.reviews(place_id);
CREATE INDEX idx_reviews_user_id ON public.reviews(user_id);

-- ============================================================================
-- 4. AUTOMATIC TRIGGERS & FUNCTIONS
-- ============================================================================

-- 4A. Automatically sync user metadata to profiles table on signup
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
    VALUES (
        new.id,
        COALESCE(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1)),
        new.email,
        COALESCE(new.raw_user_meta_data->>'avatar_url', 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150')
    )
    ON CONFLICT (id) DO UPDATE SET
        full_name = COALESCE(excluded.full_name, profiles.full_name),
        email = COALESCE(excluded.email, profiles.email),
        updated_at = timezone('utc'::text, now());
    RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_auth_user_created
    AFTER INSERT ON auth.users
    FOR EACH ROW EXECUTE PROCEDURE public.handle_new_user();

-- 4B. Secure admin check function (Checks database admin table or app_metadata role)
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN AS $$
BEGIN
    RETURN (
        COALESCE((auth.jwt() -> 'app_metadata' ->> 'role'), '') = 'admin'
        OR EXISTS (SELECT 1 FROM public.admin_users WHERE user_id = auth.uid())
    );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER STABLE;

-- 4C. Recalculate average rating of a place on review insert/update/delete
CREATE OR REPLACE FUNCTION public.update_place_rating()
RETURNS TRIGGER AS $$
DECLARE
    target_place_id BIGINT;
    avg_rate NUMERIC(3, 2);
BEGIN
    target_place_id := COALESCE(new.place_id, old.place_id);
    SELECT ROUND(COALESCE(AVG(rating), 4.5)::numeric, 2)
    INTO avg_rate
    FROM public.reviews
    WHERE place_id = target_place_id;

    UPDATE public.places
    SET rating = avg_rate
    WHERE id = target_place_id;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE TRIGGER on_review_change
    AFTER INSERT OR UPDATE OR DELETE ON public.reviews
    FOR EACH ROW EXECUTE PROCEDURE public.update_place_rating();

-- 4D. Rich View for reviews joined with user profiles
CREATE OR REPLACE VIEW public.place_reviews_view AS
SELECT
    r.id,
    r.place_id,
    r.user_id,
    r.rating,
    r.comment,
    r.created_at,
    COALESCE(p.full_name, 'CityMate Traveler') AS user_name,
    COALESCE(p.avatar_url, 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150') AS user_avatar
FROM public.reviews r
LEFT JOIN public.profiles p ON r.user_id = p.id;

-- ============================================================================
-- 5. ROW LEVEL SECURITY (RLS) POLICIES
-- ============================================================================

-- Enable RLS on all tables
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.cities ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.places ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.services ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.favourites ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;

-- 5A. PROFILES RLS
CREATE POLICY "Public profiles are viewable by everyone"
    ON public.profiles FOR SELECT
    USING (true);

CREATE POLICY "Users can insert their own profile"
    ON public.profiles FOR INSERT
    WITH CHECK (auth.uid() = id);

CREATE POLICY "Users can update their own profile"
    ON public.profiles FOR UPDATE
    USING (auth.uid() = id)
    WITH CHECK (auth.uid() = id);

-- 5B. CITIES RLS
CREATE POLICY "Cities are viewable by everyone"
    ON public.cities FOR SELECT
    USING (true);

CREATE POLICY "Only admins can insert cities"
    ON public.cities FOR INSERT
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can update cities"
    ON public.cities FOR UPDATE
    USING (public.is_admin())
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can delete cities"
    ON public.cities FOR DELETE
    USING (public.is_admin());

-- 5C. PLACES RLS
CREATE POLICY "Places are viewable by everyone"
    ON public.places FOR SELECT
    USING (true);

CREATE POLICY "Only admins can insert places"
    ON public.places FOR INSERT
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can update places"
    ON public.places FOR UPDATE
    USING (public.is_admin())
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can delete places"
    ON public.places FOR DELETE
    USING (public.is_admin());

-- 5D. SERVICES RLS
CREATE POLICY "Services are viewable by everyone"
    ON public.services FOR SELECT
    USING (true);

CREATE POLICY "Only admins can insert services"
    ON public.services FOR INSERT
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can update services"
    ON public.services FOR UPDATE
    USING (public.is_admin())
    WITH CHECK (public.is_admin());

CREATE POLICY "Only admins can delete services"
    ON public.services FOR DELETE
    USING (public.is_admin());

-- 5E. FAVOURITES RLS
CREATE POLICY "Users can view their own favourites"
    ON public.favourites FOR SELECT
    USING (auth.uid() = user_id);

CREATE POLICY "Users can insert their own favourites"
    ON public.favourites FOR INSERT
    WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can delete their own favourites"
    ON public.favourites FOR DELETE
    USING (auth.uid() = user_id);

-- 5F. REVIEWS RLS
CREATE POLICY "Reviews are viewable by everyone"
    ON public.reviews FOR SELECT
    USING (true);

CREATE POLICY "Authenticated users can insert reviews"
    ON public.reviews FOR INSERT
    WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can update their own reviews"
    ON public.reviews FOR UPDATE
    USING (auth.uid() = user_id)
    WITH CHECK (auth.uid() = user_id);

CREATE POLICY "Users can delete their own reviews"
    ON public.reviews FOR DELETE
    USING (auth.uid() = user_id);

-- 5G. ADMIN_USERS RLS
CREATE POLICY "Admins can view admin list"
    ON public.admin_users FOR SELECT
    USING (public.is_admin());

