SELECT setval('public.cities_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.cities));
SELECT setval('public.places_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.places));
SELECT setval('public.services_id_seq', (SELECT COALESCE(MAX(id), 1) FROM public.services));

